	\sqrt{\sum_{a_1, g_1} \Vert  ((G_1)^{\bx}_{[g_1(\by_1) = a_1]} \cdot (G_2)^{\bx}_{g_2} \cdot (G_1)^{\bx}_{[g_1(\by_1) = a_1]} \otimes I_{\reg{Bob}}) \ket{\psi} \Vert^2}\\
